$_MODULE['<{ntbackupandrestore}prestashop>faq_42027eaa203032a09ccc5048897c677c'] = 'Automatiseringen af 2N synes ikke at virke længere, hvad kan jeg gøre?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_ffebb8fcef9bdccc3aeac353e6d78be7'] = 'Prøv at gemme den igen';
$_MODULE['<{ntbackupandrestore}prestashop>faq_41906c69303e903c986fde8f7cb34665'] = 'Backup sluttede med en fejl, der angiver, at der ikke er nok plads til backup, men jeg ved, at der er. Hvorfor har jeg denne fejl?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_8bdbb9087cc2864414759889f6d22307'] = 'Denne fejl kan skyldes en grænse for serveren. Nogle server (32 bits) tillader ikke backup at være på mere end 2 GB. I dette tilfælde kan du bruge den avancerede indstilling til at begrænse størrelsen på sikkerhedskopieringen. Sikkerhedskopieringen vil blive skåret i mindre dele, der vil blive accepteret af din server. vælge 1500 som størrelsesgrænsen for sikkerhedskopifilstørrelsen. Vær opmærksom på, at alle dele er obligatoriske, hvis du ønsker at gendanne din butik.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_afde1c7273735610102d9f166386b91e'] = 'Hvor kan jeg finde sikkerhedskopien på min server?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_c99296863a8cfebedbf941a80b149eb3'] = 'Du kan finde sikkerhedskopien i mappemodulerne/ntbackupandrestore/backup/ som standard eller i den mappe, du har konfigureret i avanceret konfiguration.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_6162f1ad35f8d68d2ad18e65d6af12ca'] = 'Hvor kan jeg finde databasedumpet i min sikkerhedskopi?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_259f134b1c3cb0f4211d27812fb4f339'] = 'Når du opretter en komplet sikkerhedskopi, gemmes databasen sammen med alle andre filer i sikkerhedskopifilen. Hvis du vil kontrollere, skal du fjerne størrelsen på sikkerhedskopifilen på computeren, du kan finde dumpet. SQL i mappemodulerne/Ntbackupandrestore/backup/';
$_MODULE['<{ntbackupandrestore}prestashop>faq_d50856eaf5567a344aafac6b6629a581'] = 'Hvordan kan jeg kontrollere, at min sikkerhedskopi er gyldig?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_d2a25247fc786e9f6a27212ee9aed0b8'] = 'Den bedste måde at sikre, at din backup er gyldig, er at forsøge at gendanne den et andet sted. For eksempel på et nyt domæne og ny database eller på din computer med Wamp, Mamp, Easyphp eller andre lokale server software.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_b26bae87fdb843d75a120d12fe51ffa6'] = 'Hvordan kan jeg gendanne min sikkerhedskopi?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_84d3c56657e5438d10f92c3d36c5cf8b'] = 'Hvis du vil gendanne sikkerhedskopien, skal du:';
$_MODULE['<{ntbackupandrestore}prestashop>faq_261aa829c8bd1bd4216bf09dc76f7326'] = 'Vælg, hvor du handler, vil blive restaureret. Enten på et nyt sted (nyt domæne og ny database) til en kopi/flytning eller roden til din nuværende butik for at blive udskiftet.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_0c02578d80e75b15e3c2fafda964bfe4'] = 'Placer sikkerhedskopien og gendannelsesscriptet på vælgerens placering';
$_MODULE['<{ntbackupandrestore}prestashop>faq_967e66ec729f29106f185bf0e5c9c267'] = 'Få adgang til gendannelsesscriptet ved hjælp af webbrowseren';
$_MODULE['<{ntbackupandrestore}prestashop>faq_96c158c212b69d93f4bf51a208b7c6b0'] = 'Udfyld adgangslegitimationsoplysningerne i den database, hvor data gendannes.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_3438a63edfc1456e8bff9b8a75f0f8c2'] = 'Valgfrit: Konfigurer om nødvendigt de avancerede indstillinger';
$_MODULE['<{ntbackupandrestore}prestashop>faq_0b20e24f98a55bf66d6fe76363284591'] = 'Start restaureringen. Vær opmærksom på, at filer fra din sikkerhedskopi vil overskrive potentielle eksisterende filer og database vil blive erstattet af databasen fra din backup.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_6510898b2f7a8fa6fe8aeafb9ea5ca4d'] = 'Skal jeg først installere en tom Prestashop for at gendanne min butik?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_2f8b950c8cb11678dd68bd1050f15034'] = 'Du behøver ikke at installere en tom Prestashop for at gendanne. Du behøver kun din sikkerhedskopi fil og restaurering script.';
