$_MODULE['<{ntbackupandrestore}prestashop>faq_e1b5007baa84a263669be3be91779369'] = 'Indeholder den komplette sikkerhedskopi virkelig alle mine filer og data?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_d22b5ed685107fdea35dd423a0adc8e4'] = 'Den komplette sikkerhedskopi indeholder en nøjagtig kopi af dit websted, hvilket betyder alle dine filer og data, undtagen filer og data af lav interesse (cacher, logfiler ...), som ikke gemmes, fordi deres størrelse er stor, og de er til ringe nytte under en gendannelse. Du kan ikke desto mindre bede modulet om at gemme dem i de avancerede indstillinger.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_c7b627aacbd45fc86611dc65afcd11fc'] = 'Jeg har ikke nok plads på min server til sikkerhedskopien, kan jeg sende den direkte til en af mine fjernkonti (%1$s, %2$s ...)?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_0ec06b6f186a84a008827f4ee4efdff2'] = 'Før den kan sendes til en fjernkonto, skal sikkerhedskopien oprettes på din server. Du skal mindst have plads til en sikkerhedskopi. Du kan i den avancerede konfiguration vælge den mulighed, der tillader automatisk sletning af den lokale sikkerhedskopi, hvis den sendes til en fjernkonto. Hvis du ikke har plads nok til en sikkerhedskopi, kan du aktivere direkte afsendelse (uden lokal sikkerhedskopi) til fjernserveren (undtagen FTP og Box), men i dette tilfælde komprimeres sikkerhedskopien ikke.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_50fe9d94822e8a6d1ed52600d8c071cc'] = 'Hvordan opdateres modulet?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_c45a02babc859c783cc1a5b21b62cdfd'] = 'Du skal downloade den sidste version af modulet fra det tidspunkt, hvor du har købt det.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_cf832f19d14486b25d11aaf8e9cc016d'] = 'Klik derefter på knappen Installer modul i Modules > Modules Manager i din butiks backoffice i din butik og vælg modulets zip-fil.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_a9f902c1ce6abfbf5cd3573d49973d87'] = 'Prestashop registrerer din aktuelle version og opdaterer automatisk dit modul.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_3384251ff34a299aae3717020c8e0bfd'] = 'Det er ikke nødvendigt at afinstallere modulet først.';
$_MODULE['<{ntbackupandrestore}prestashop>restoration_c4384e636370b73a93481c67d7b7b93d'] = 'ADVARSEL! Arkivfiler, der er anført nedenfor, findes ved din butiks rod. Dette er usædvanligt. Hvis de er sikkerhedskopifiler, kan du flytte dem tilbage til modulet ved at klikke på flytteknappen.';
