$_MODULE['<{ntbackupandrestore}prestashop>faq_6ddd16646b753dd26ee53747b23a2ec2'] = 'Denne fejl vises, når gendannelsesscriptet ikke udtrækker alle filer fra sikkerhedskopien.';
