$_MODULE['<{ntbackupandrestore}prestashop>faq_262f7483c7092812bb191d7c2d78607b'] = 'I dette tilfælde skal du sende filen igen.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_6c1ae0000beadc52954940b7550c1d1e'] = 'Din sikkerhedskopifil er mere end 2 GB, men serveren, hvor du sikkerhedskopierer eller gendanner den, understøtter ikke filer, der er større end 2 GB.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_e61f34d2d23bbca6a6f7b37436d2f7cf'] = 'I modulets avancerede konfiguration skal du ændre indstillingen \"Maksimal størrelse (i MB) for dine sikkerhedskopifiler\" til 2000 og udføre en sikkerhedskopi igen.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_d4093b868ce07bfa66b059439835fcd5'] = 'Din sikkerhedskopi opdeles derefter i flere mindre filer. Kopier dem alle til det sted, hvor du vil gendanne, og kør gendannelsen igen.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_06868981ac8bfa6de6d5055e937db92c'] = 'Mere sjældent, men det kan ske, har sikkerhedskopifilen et problem.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_9834182030715013f543b0dd2cfbef7e'] = 'For at være sikker skal du åbne den med en standardkomprimeringssoftware som 7zip, winrar, winzip...';
$_MODULE['<{ntbackupandrestore}prestashop>faq_e36bf213cae9b17180502b4611875cd6'] = 'Hvis softwaren formår at åbne filen uden fejl, er filen korrekt. Ellers var der et problem under sikkerhedskopien.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_5f5785040a675eb5bf2b05ed270e4554'] = 'Hvis du på trods af dette stadig har et problem, tøv ikke med at kontakte os.';
